@router.post("/api/host-containment/{asset_name}")
def request_host_containment(asset_name: str, reason: str = "Solicitud manual desde el dashboard"):
    """
    Creates a HOST-CONTAINMENT-REQUEST finding for the named asset. Deliberately does NOT
    execute anything directly -- this flows through the exact same correlate -> human approval
    -> Sentinel execution pipeline as every other remediation in this system. Emergency
    containment is disruptive (cuts off nearly all network access to the host) and must never
    fire without an explicit human approval in the SOAR UI, the same safety net every other
    action in this system already has.
    """
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("SELECT id, endpoint FROM public.infra_inventory WHERE asset_name = %s", (asset_name,))
            asset = cur.fetchone()
        if not asset:
            raise HTTPException(status_code=404, detail=f"Asset '{asset_name}' not found")

        from core import deduplication_engine
        description = f"**Solicitud de contención de emergencia**\n\n**Motivo:** {reason}"
        with db_manager.get_db_cursor() as cur:
            action, vuln_id = deduplication_engine.log_finding_deduplicated(
                cur, asset["id"], "HOST-CONTAINMENT-REQUEST", "CRITICAL", description,
                "manual-containment", open_status="PENDING"
            )
        return {"status": "requested", "vuln_id": vuln_id, "action": action,
                "message": "Solicitud creada. Requiere aprobación en el SOAR para ejecutarse."}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.websocket("/api/ws/alerts")
async def websocket_endpoint(websocket: WebSocket):
    from core.auth import ws_authorize, _ws_token, WS_SUBPROTOCOL
    if not await ws_authorize(websocket):
        await websocket.close(code=1008)      # policy violation: missing/invalid token (enforce mode)
        return
    # if the client offered our subprotocol the server must echo it, otherwise the browser aborts the connection
    await manager_ws.connect(websocket, subprotocol=WS_SUBPROTOCOL if _ws_token(websocket) else None)
    try:
        while True:
            await websocket.receive_text()
    except WebSocketDisconnect:
        manager_ws.disconnect(websocket)


@router.post("/api/itdr/authentik/webhook")
def authentik_itdr_webhook(payload: dict, request: Request):
    """
    Ingests and processes real-time authentication events from Authentik IdP for Identity Threat Detection (ITDR).

    If ITDR_WEBHOOK_TOKEN is set, the caller must present it as a bearer token or an
    X-Centinela-Token header -- otherwise this is an unauthenticated ingestion point anyone on
    the network could push fake identity alerts into. When the var is unset the endpoint stays
    open (backwards-compatible), but a warning is logged so it doesn't silently stay that way.
    """
    expected = os.getenv("ITDR_WEBHOOK_TOKEN", "").strip()
    if expected:
        presented = (
            request.headers.get("x-centinela-token", "").strip()
            or request.headers.get("authorization", "").removeprefix("Bearer ").strip()
        )
        if presented != expected:
            raise HTTPException(status_code=401, detail="Invalid or missing ITDR webhook token")
    else:
        print("⚠️ [ITDR-Webhook] ITDR_WEBHOOK_TOKEN not set -- webhook is accepting unauthenticated events.")

    try:
        res = itdr_engine.process_authentik_event(payload)
        return res
    except Exception as e:
        print(f"⚠️ [ITDR-Webhook-Error] {e}")
        return {"status": "error", "detail": str(e)}


@router.get("/api/itdr/telemetry/recent")
async def get_recent_itdr_telemetry(minutes: int = 15):
    """
    Queries high-throughput identity & EDR telemetry events from ClickHouse,
    with automatic fallback to PostgreSQL runtime_alerts so ITDR panel always displays live telemetry.
    """
    events = await asyncio.to_thread(clickhouse_manager.query_recent_events, minutes)
    if not events:
        try:
            with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
                cur.execute("""
                    SELECT 
                        detected_at as timestamp,
                        'authentik_itdr' as source,
                        rule_name as event_type,
                        COALESCE(asset_name, 'Authentik') as username,
                        r.output_fields->>'client_ip' as client_ip,
                        priority as severity,
                        alert_text as details,
                        (r.output_fields->>'confidence_score')::float as confidence_score
                    FROM public.runtime_alerts r
                    LEFT JOIN public.infra_inventory i ON r.asset_id = i.id
                    WHERE rule_name LIKE 'ITDR%%' OR rule_name LIKE 'AUTHENTIK%%'
                    ORDER BY detected_at DESC LIMIT 100
                """)
                events = [dict(r) for r in cur.fetchall()]
        except Exception as e:
            print(f"⚠️ [ITDR-Fallback] Postgres query failed: {e}")
            events = []

    return {"events": events, "count": len(events)}


