@router.post("/api/xdr/soar/evaluate")
def evaluate_soar_response(payload: dict, request: Request):
    """
    Evaluates and (per policy) dispatches Tiered Autonomous Response (confidence >= 95%).
    Can trigger a real network block once a policy has dry_run=FALSE, so it requires the same
    secret as the ITDR ingestion webhook (bearer or X-Centinela-Token) and fails closed if unset.
    """
    import hmac
    expected = os.getenv("ITDR_WEBHOOK_TOKEN", "").strip()
    presented = (request.headers.get("x-centinela-token", "").strip()
                 or request.headers.get("authorization", "").removeprefix("Bearer ").strip())
    if not expected or not hmac.compare_digest(presented.encode(), expected.encode()):
        raise HTTPException(status_code=401, detail="Invalid or missing token")
    res = soar_engine.evaluate_and_execute_response(
        rule_name=payload.get("rule_name", "UNKNOWN_RULE"),
        asset_name=payload.get("asset_name", ""),
        client_ip=payload.get("client_ip", ""),
        username=payload.get("username", ""),
        confidence_score=float(payload.get("confidence_score", 0.90)),
        cti_hit=bool(payload.get("cti_hit", False)),
        severity=str(payload.get("severity", "HIGH")),
    )
    return res



